if (typeof L === 'undefined') {
setTimeout(initMap, 100);
return;
}
mapInitialized = true;
map = L.map('leaflet-map', {
center: [51.1310, 0.2470],
zoom: 14,
scrollWheelZoom: false
});
map.on('click', () => map.scrollWheelZoom.enable());
